def compute(vars):
    operating_cash_millions = vars["v1"]
    cash_equivalents_billions = vars["v2"]
    cash_equivalents_millions = cash_equivalents_billions * 1000

    if cash_equivalents_millions == 0:
        return None

    ratio = operating_cash_millions / cash_equivalents_millions
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "operating_cash_millions": operating_cash_millions,
            "cash_equivalents_millions": cash_equivalents_millions,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
